TreeNode* Next(TreeNode* currentNode)
{
TreeNode* temp = currentNode->RightChild;
if (currentNode->RightThread == 0)
while (temp->LeftThread == 0)
temp = temp->LeftChild;
currentNode = temp;
if (currentNode == headNode)
return 0;
